protocol Drawable {
    var color: String { get }
    func draw()
}

struct Circle: Drawable {
    var color: String
    var radius: Double

    func draw() {
        print("Drawing \(color) circle with radius \(radius)")
    }
}

struct Square: Drawable {
    var color: String
    var side: Double

    func draw() {
        print("Drawing \(color) square with side \(side)")
    }
}

// Code to the protocol, not the concrete type
func render(_ shape: Drawable) {
    shape.draw()
}

protocol Greetable {
    var name: String { get }
    func greet() -> String
}

// Default implementation via extension
extension Greetable {
    func greet() -> String {
        "Hello, I'm \(name)!"
    }
}

struct User: Greetable {
    var name: String
    // Gets greet() for free!
}

struct Bot: Greetable {
    var name: String
    // Override the default
    func greet() -> String {
        "Beep boop, I'm \(name)."
    }
}

print(User(name: "Alice").greet()) // Hello, I'm Alice!
print(Bot(name: "R2").greet())      // Beep boop, I'm R2.

protocol Repository {
    associatedtype Item
    func getAll() -> [Item]
    func save(_ item: Item)
}

struct UserRepository: Repository {
    // Swift infers Item == User from the signatures
    func getAll() -> [User] {
        return database.fetchUsers()
    }
    func save(_ item: User) {
        database.insert(item)
    }
}

// Use with 'some' (opaque type)
func printItems(from repo: some Repository) {
    for item in repo.getAll() {
        print(item)
    }
}

// Or with generic constraint
func sync<R: Repository>(repo: R) where R.Item: Codable {
    let items = repo.getAll()
    upload(items)
}
